@js:(function(){
  try {
    var bookIdM = String(baseUrl).match(/[?&]bookId=([^&#,]+)/);
    if (!bookIdM || !bookIdM[1]) return '⚠️ 缺少bookId参数';
    var bookId = bookIdM[1];
    var ua = 'Mozilla/5.0 (Linux; Android 16; 25102RKBEC Build/BP2A.250605.031.A3) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/140.0.0.0 Mobile Safari/537.36';

    // ============ 通道1：LITE API（重试5次，遇403抖动） ============
    var liteParams = 'device_platform=android&os=android&_rticket=' + Date.now() + '&cdid=c940b404-2b15-48bb-b9cb-24907ce66ecb&channel=53931575a&aid=8661&app_name=novel_fm_lite&version_code=624&version_name=6.2.4.32&manifest_version_code=624&update_version_code=62432&resolution=540*960&dpi=240&device_type=PGAM10&device_brand=OPPO&language=zh&os_api=32&os_version=12&ac=wifi&host_abi=arm64-v8a';
    var body = JSON.stringify({audio_type:0, bgm_used:0, book_id:bookId, device_score:0.0, item_ids:[bookId], multi_shift:true, source:'music_continuous_preload_more', tone_id:0, user_select_start_para:0, user_select_start_para_off:0});
    var liteOpt = {method:'POST', headers:{'User-Agent': ua, 'Content-Type':'application/json', 'Referer':'https://m.novelfm.com/', 'Origin':'https://m.novelfm.com'}, body: body};
    var liteUrl = 'https://api5-lite-sinfonlineb.novelfm.com/novelfm/playerapi/video_model/mget/v1/?' + liteParams;
    var lastCode = null;
    for (var attempt = 0; attempt < 5; attempt++) {
      try {
        var resp = String(java.ajax(liteUrl + ',' + JSON.stringify(liteOpt)));
        var j = JSON.parse(resp);
        if (j && j.code === 0) {
          var vmds = (j.data && j.data.video_model_datas) || [];
          if (vmds.length) {
            var vmRaw = vmds[0].video_model;
            var vm = typeof vmRaw === 'string' ? JSON.parse(vmRaw) : vmRaw;
            if (vm && vm.status === 10) {
              var list = vm.video_list || [];
              var order = ['highest','higher','medium'];
              for (var oi = 0; oi < order.length; oi++) {
                for (var i = 0; i < list.length; i++) {
                  var v = list[i] || {};
                  var meta = v.video_meta || {};
                  if (meta.quality === order[oi] && (v.main_url || v.url)) return String(v.main_url || v.url);
                }
              }
              for (var k = 0; k < list.length; k++) {
                if (list[k] && (list[k].main_url || list[k].url)) return String(list[k].main_url || list[k].url);
              }
            }
          }
        } else if (j && j.code === 5000) {
          return '⚠️ 平台限制播放（版权曲目）';
        } else {
          lastCode = j && j.code;
        }
      } catch (e) {
        lastCode = 'err';
      }
    }

    // ============ 通道2：SSR 兜底（m站歌曲页抓 video_info.main_url） ============
    try {
      var ssrOpt = {method:'GET', headers:{'User-Agent': ua, 'Accept':'text/html,application/xhtml+xml', 'Referer':'https://www.novelfm.com/'}};
      var ssrUrl = 'https://m.novelfm.com/music/' + bookId;
      var ssrHtml = String(java.ajax(ssrUrl + ',' + JSON.stringify(ssrOpt)));
      var m = /window\._ROUTER_DATA\s*=\s*(\{[\s\S]*?\});?\s*<\/script>/.exec(ssrHtml);
      if (m) {
        var rd = JSON.parse(m[1]);
        if (rd && rd.loaderData) {
          for (var lk in rd.loaderData) {
            var lv = rd.loaderData[lk];
            if (lv && typeof lv === 'object' && lv.pageData && lv.pageData.video_info) {
              var vi = lv.pageData.video_info;
              if (vi.main_url) return String(vi.main_url);
              if (vi.back_url) return String(vi.back_url);
            }
          }
        }
      }
    } catch (e2) {}

    return '⚠️ 取链失败：LITE code=' + lastCode + '，SSR兜底也失败';
  } catch (e) {
    return '⚠️ 异常：' + e.message;
  }
})()

ruleContent.subContent:
@js:(function(){
  try {
    var bookIdM = String(baseUrl).match(/[?&]bookId=([^&#,]+)/);
    if (!bookIdM || !bookIdM[1]) return '[00:00.00]暂无歌词';
    var bookId = bookIdM[1];
    var ua = 'Mozilla/5.0 (Linux; Android 16; 25102RKBEC Build/BP2A.250605.031.A3) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/140.0.0.0 Mobile Safari/537.36';
    var opt = {method:'GET', headers:{'User-Agent': ua, 'Accept':'text/html,application/xhtml+xml'}};
    var url = 'https://m.novelfm.com/music/' + bookId;
    var html = String(java.ajax(url + ',' + JSON.stringify(opt)));
    var m = /window\._ROUTER_DATA\s*=\s*(\{[\s\S]*?\});?\s*<\/script>/.exec(html);
    if (!m) return '[00:00.00]歌词页解析失败';
    var rd = JSON.parse(m[1]);
    var pageData = null;
    if (rd && rd.loaderData) {
      for (var k in rd.loaderData) {
        var v = rd.loaderData[k];
        if (v && typeof v === 'object' && v.pageData && typeof v.pageData === 'object') { pageData = v.pageData; break; }
      }
    }
    if (!pageData) return '[00:00.00]歌词数据缺失';
    var lyricType = Number(pageData.lyric_type) || 0;
    var lyricInfo = typeof pageData.lyric_info === 'string' ? pageData.lyric_info : '';
    if (!lyricInfo) return '[00:00.00]暂无歌词';
    if (lyricType === 1) return lyricInfo;
    if (lyricType === 2) {
      var lines = lyricInfo.split('\n');
      var out = '';
      for (var i = 0; i < lines.length; i++) {
        var head = /^\[(\d+),\d+\]/.exec(lines[i]);
        if (!head) continue;
        var text = lines[i].replace(/^\[\d+,\d+\]/, '').replace(/<\d+,\d+(?:,[^>]*)?>/g, '').trim();
        if (!text) continue;
        var ms = parseInt(head[1], 10);
        var mm = Math.floor(ms / 60000);
        var ss = Math.floor((ms % 60000) / 1000);
        var mmm = ms % 1000;
        out += '[' + (mm < 10 ? '0' : '') + mm + ':' + (ss < 10 ? '0' : '') + ss + '.' + (mmm < 10 ? '00' : (mmm < 100 ? '0' : '')) + mmm + ']' + text + '\n';
      }
      return out || '[00:00.00]暂无歌词';
    }
    return '[00:00.00]暂无歌词';
  } catch (e) {
    return '[00:00.00]歌词异常：' + e.message;
  }
})()

