@js:(function(){
var kwM = String(baseUrl).match(/[?&]cat=([^&#]+)/);
var qM = String(baseUrl).match(/[?&]q=([^&#]+)/);
var list = [];
var searchWord = '';
if (kwM && kwM[1]) { searchWord = decodeURIComponent(kwM[1]); }
else if (qM && qM[1]) { searchWord = decodeURIComponent(qM[1]); }
if (searchWord) {
  var ua = 'Mozilla/5.0 (Linux; Android 16; 25102RKBEC Build/BP2A.250605.031.A3) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/140.0.0.0 Mobile Safari/537.36';
  var rt = Date.now();
  var ps = 'device_platform=android&os=android&ssmix=a&_rticket='+rt+'&cdid=b501fece-ed1e-4f02-8939-28439d91364e&channel=vivo_3040_64&aid=3040&app_name=novel_fm&version_code=556&version_name=5.5.6.32&manifest_version_code=556&update_version_code=55632&resolution=1080*2272&dpi=440&device_type=M2012K10C&device_brand=Redmi&language=zh&os_api=33&os_version=13&ac=wifi&device_id=4135726972408180&need_personal_recommend=1&iid=3563956292032601&comment_tag_c=5&vip_state=0&category_style=1';
  var body = JSON.stringify({limit:20,offset:0,query:searchWord,search_ctx_info:'',search_entrance:'',search_id:'',sub_tab_type:32,tab_type:3});
  var opt = {method:'POST',headers:{'User-Agent':ua,'Content-Type':'application/json'},body:body};
  try {
    var resp = String(java.ajax('https://api5-sinfonlinea.novelfm.com/novelfm/bookmall/search/page/v1/?'+ps+','+JSON.stringify(opt)));
    var j = JSON.parse(resp);
    var sds = (j.data && j.data.search_data) || [];
    var curM = String(baseUrl).match(/[?&]bookId=([^&#]+)/);
    var curId = curM ? curM[1] : '';
    for (var i = 0; i < sds.length; i++) {
      var books = sds[i].books || [];
      for (var k = 0; k < books.length; k++) {
        var b = books[k];
        if (!b || !b.book_id) continue;
        var names = [];
        var ais = b.author_infos || [];
        for (var a = 0; a < ais.length; a++) { if (ais[a] && ais[a].name) names.push(ais[a].name); }
        var dur = Number(b.audio_duration) || 0;
        var albumName = (b.common_book_info && b.common_book_info.album_title) || '';
        var u = 'https://m.novelfm.com/music/' + b.book_id + '?bookId=' + b.book_id + '&name=' + encodeURIComponent(b.book_name || '') + '&singer=' + encodeURIComponent(names.join('/')) + '&album=' + encodeURIComponent(albumName) + '&dur=' + dur + '&cover=' + encodeURIComponent(b.thumb_url || '') + '&cat=' + encodeURIComponent(searchWord);
        list.push({name: String(b.book_name || '').replace(/<\/?em>/g, ''), url: u});
      }
    }
    // 当前歌移到最前（从当前开始连播）
    if (curId) {
      var curIdx = -1;
      for (var x = 0; x < list.length; x++) { if (list[x].url.indexOf(curId) > -1) { curIdx = x; break; } }
      if (curIdx > 0) { var cur = list.splice(curIdx, 1)[0]; list.unshift(cur); }
    }
  } catch(e) {}
}
if (!list.length) { list.push({name:'整曲播放', url: baseUrl}); }
return list;
})()

